//! **The ALS clip → mode map, and the graph it builds** (wave CHAR1b.1,
//! clause 2).
//!
//! P29 shipped a fourteen-mode movement catalogue, `RotationMode`,
//! turn-in-place rules, blend spaces, inertialization and a state-machine
//! runtime. What it never had was a *graph*: the island's hero — and every
//! committed sample — plays a three-state machine of `idle` / `walk` / `run`
//! generated by the P24 wizard, so eleven of the fourteen modes had no animation
//! at all and the three that did had one clip each and no direction.
//!
//! This module is the other half: a table saying which ALS sequence fills which
//! slot of a locomotion graph, and a builder that turns that table plus a
//! name→clip resolver into a [`StateMachine`].
//!
//! # Names, not assets
//!
//! **ALS-Community is MIT and its assets never enter this checkout.** What is
//! written down here is the *name* of each sequence — a fact about the donor's
//! catalogue, in the same way a port map records a function name — and a
//! resolver hands back whatever GUID the local import gave it. On a machine with
//! no ALS content [`build_locomotion_graph`] answers a graph with the slots it
//! could fill and a list of the ones it could not, which is what lets CI hold a
//! table it has no assets for.
//!
//! # Why a table and not a generator
//!
//! [`crate::locomotion`] *derives* a cycle from a rig, which is the right shape
//! when there is no content. Here there is content: 164 authored sequences whose
//! author decided what a left-forward run looks like. A generator would throw
//! that away. The table's job is to say which is which, once, where a reviewer
//! can read it against the donor's own folder listing.
//!
//! # The mode discriminants live in `inf-ecs` and are mirrored here
//!
//! `inf-anim` is below `inf-ecs` in the ring order and cannot name
//! `MovementMode`. [`LocoMode`] therefore carries the discriminant as a number
//! and `char1b_gate::the_two_mode_tables_agree` holds the two together — the
//! standing law about a table spelled in two crates.

use crate::blend_space::ClipRef;
use crate::blend_space::{BlendEntry2D, BlendSpace2D};
use crate::state_machine::{
    BlendCurve, CmpOp, Motion, SmCompare, SmCond, SmParam, SmState, SmTransition, StateMachine,
};

/// **The state whose blend space is the look/aim sweep** — the three
/// `ALS_N_Look_{U,F,D}_Sweep` sequences, sampled by `inf_ecs::pose`'s additive
/// layer at the aim's own pitch.
///
/// A name and not an index, because a machine a human edited afterwards has
/// different indices and the same names.
pub const LOOK_SWEEP_STATE: &str = "aim_look";
/// The state whose clip is the **breathing additive** (wave CHAR1b.2, carried
/// item 128) — `ALS_N_SecondaryMotion`, layered over the idle through the
/// upper-body mask rather than entered.
pub const BREATH_STATE: &str = "breath";
/// The two states whose clips are the **throw additives** (wave CHAR1b.2) —
/// `INF_Throw_Over` and `INF_Throw_Under`, layered over whatever the character
/// is doing rather than entered, so a grenade can be thrown mid-run.
pub const THROW_OVER_STATE: &str = "throw_over";
/// See [`THROW_OVER_STATE`].
pub const THROW_UNDER_STATE: &str = "throw_under";
/// The state whose clip is the **blind-fire additive** (wave WPN2e) —
/// `INF_Cover_BlindFire`, layered over whatever cover stance the machine is in
/// rather than entered, because a character firing blind is still in cover and a
/// state would replace the stance the shot is taken from.
pub const BLIND_FIRE_STATE: &str = "cover_blind_fire";

/// **The stance overlay every character wears** (wave WPN2b) —
/// `ALS_StanceVariation_Normal`, layered over the idle through the upper-body
/// mask.
///
/// ALS layers a stance variation at ALL times and this engine layered none,
/// which is the CHAR1b.1 audit's own finding: the idle's arms hang wide because
/// nothing was bringing them in. `inf_ecs::pose`'s overlay pass is the reader.
pub const OVERLAY_DEFAULT_STATE: &str = "overlay_default";

/// **The long-gun overlay** (wave WPN2b) — `ALS_Props_M4A1_Poses`, worn by
/// every weapon in the registry whose barrel is not a handgun's.
pub const OVERLAY_M4A1_STATE: &str = "overlay_m4a1";

/// **The two-handed pistol overlay** (wave WPN2b) —
/// `ALS_Props_Pistol_2H_Poses`, worn by the registry's ten handguns.
///
/// Two-handed and not `overlay_pistol_1h`, which is still reachable and still
/// undriven: a modern shooter holds a sidearm with both hands, and the one-handed
/// set is the casual carry an author asks for by name through
/// `CharacterMovement::overlay`.
pub const OVERLAY_PISTOL_2H_STATE: &str = "overlay_pistol_2h";

/// **The long-gun aim sweep** (wave WPN2b) — `ALS_Props_M4A1_Aim_Sweep` and its
/// crouched sample, layered in as the aim-down-sights blend comes up.
pub const AIM_M4A1_STATE: &str = "aim_m4a1";

/// **The two-handed pistol aim sweep** (wave WPN2b).
pub const AIM_PISTOL_2H_STATE: &str = "aim_pistol_2h";

/// **The coordinate a weapon aim sweep's STANDING sample sits at** (wave WPN2b).
///
/// The prop sweeps are two-sample blend spaces — `[0, 0]` standing and
/// `[0, -1]` crouched (see the rows below) — so their second axis is the STANCE
/// and not the pitch, which is what the look sweep's is. Driving one with the
/// other's coordinate would make a character aiming downhill crouch, and that is
/// the reason the two are separate constants rather than one.
pub const WEAPON_SWEEP_STANDING: [f64; 2] = [0.0, 0.0];

/// **The coordinate a weapon aim sweep's CROUCHED sample sits at** (wave WPN2b).
pub const WEAPON_SWEEP_CROUCHED: [f64; 2] = [0.0, -1.0];

/// The blend coordinate the look sweep's **neutral** sits at — the pose the
/// additive delta is measured from.
///
/// `ALS_N_Look_F_Sweep` is the middle sample and is what "looking straight
/// ahead" means, so the delta at that coordinate is exactly zero and a character
/// looking forward is byte-identical to one with no layer at all. That identity
/// is a gate arm.
pub const LOOK_SWEEP_NEUTRAL: [f64; 2] = [0.0, 0.0];

/// The parameter a machine reads for planar ground speed, m/s.
///
/// `inf_ecs::anim_bridge::params::SPEED` by construction, and
/// [`crate::locomotion::SPEED_VAR`] before that: three spellings of one word
/// would leave a character standing still, which is the defect P29.6 already
/// paid for once.
pub const SPEED_VAR: &str = crate::locomotion::SPEED_VAR;
/// The 0–3 gait scale — `inf_ecs::anim_bridge::params::GAIT`.
pub const GAIT_VAR: &str = "gait";
/// The [`LocoMode`] discriminant — `inf_ecs::anim_bridge::params::MODE`.
pub const MODE_VAR: &str = "mode";
/// `1` while the last sweep ended on the ground.
pub const GROUNDED_VAR: &str = "grounded";
/// Downward speed, m/s, positive falling.
pub const FALL_SPEED_VAR: &str = "fall_speed";
/// How close a predicted landing is, `[0, 1]`.
pub const LAND_ALPHA_VAR: &str = "land_alpha";
/// **What the landing classifier decided about the last landing** — the
/// `inf_ecs::components::LandingKind` discriminant.
///
/// The landing states are gated on this and not on [`LAND_ALPHA_VAR`], which is
/// a prediction the movement step CLEARS the moment the character is grounded:
/// a graph that read the prediction could never enter a landing state, because
/// at the instant `grounded` goes true the prediction is already zero. Found by
/// reading the producer rather than by watching a character never land.
pub const LANDING_VAR: &str = "landing";
/// **Seconds since that landing** — how a one-shot landing state knows it is
/// over, and what stops one firing again on the next step.
pub const TIME_SINCE_LAND_VAR: &str = "time_since_land";

/// `LandingKind::Soft` — under the hard threshold, keep running.
pub const LANDING_SOFT: f64 = 1.0;
/// `LandingKind::Hard` — plant, with the heavier braking friction.
pub const LANDING_HARD: f64 = 2.0;
/// `LandingKind::Roll` — a break-fall into a roll.
pub const LANDING_ROLL: f64 = 3.0;
/// How long after a touch a landing state may still be entered, seconds.
pub const LANDING_WINDOW_S: f64 = 0.12;
/// **How far a turn-in-place is turning**, degrees, signed — negative to the
/// character's left. `0` when none is running.
pub const TURN_DEG_VAR: &str = "turn_deg";
/// **Which foot is planted**: `-1` left, `+1` right, `0` neither.
pub const PLANTED_FOOT_VAR: &str = "planted_foot";
/// **Whether a ragdolled character is on its back**, `1` or `0`.
pub const FACE_UP_VAR: &str = "face_up";
/// **Which get-up a ragdoll ends in** (wave CHAR1b.2): `0` none, `1` face down,
/// `2` on its back, `3` still on its feet.
///
/// ALS chooses between its two get-ups by the pelvis's facing and ships only the
/// crouched pair, so a character whose ragdoll settled UPRIGHT — knocked about
/// and never actually floored — had nowhere to go but a get-up off the ground it
/// was not on. The third value is measured, not assumed: the ragdoll bridge has
/// recorded the pelvis's world position since P29.4, and "the pelvis is still
/// more than half a capsule above the feet" is what standing means.
///
/// [`FACE_UP_VAR`] stays published and unchanged; this is the parameter the
/// three get-up edges compare, because a two-valued signal cannot name three
/// outcomes.
///
/// # Why zero is NONE, and not "face down"
///
/// Because this parameter is also **what holds a get-up on the screen**. The
/// `Any → idle` edge exists so that a character in any grounded state with no
/// speed ends up standing; it has priority 5 and no exit time, so it took the
/// machine out of a get-up on the very next step after the get-up was entered —
/// measured on the island, `getup_back` lasted **one fixed step** and the
/// ragdoll then blended out into `idle` instead of into a get-up clip. The edge
/// is guarded on `getup == GETUP_NONE` now, so a running get-up is not cut
/// short, and that guard is only correct if a character that has never
/// ragdolled reads NONE — which is what a `SmParam::float`'s zero default gives
/// for free. Making "face down" the zero would have frozen the `Any → idle`
/// edge shut on every character in the engine.
pub const GETUP_VAR: &str = "getup";
/// [`GETUP_VAR`]'s value when no get-up is running — the declared default.
pub const GETUP_NONE: f64 = 0.0;
/// [`GETUP_VAR`]'s value for a character face down.
pub const GETUP_FRONT: f64 = 1.0;
/// [`GETUP_VAR`]'s value for a character on its back.
pub const GETUP_BACK: f64 = 2.0;
/// [`GETUP_VAR`]'s value for a character that never went down.
pub const GETUP_STANDING: f64 = 3.0;
/// The get-up states, by name — the family the `Any → idle` edge must not cut
/// short, and the family the movement step watches to know when to put
/// [`GETUP_VAR`] back to [`GETUP_NONE`].
pub const GETUP_STATES: [&str; 3] = ["getup_front", "getup_back", "getup_standing"];
/// **Which mantle is running** (wave CHAR1b.2), and which hand leads it.
///
/// `0` none, `1` a low mantle led by the right hand, `2` a low mantle led by the
/// left, `3` a high one. Four values in one parameter rather than two
/// parameters, because ALS's own classification is one enum
/// (`EALSMantleType` — `LowMantle`, `HighMantle`, `FallingCatch`) crossed with
/// `GetMantleAsset(MantleType, CurrentOverlayState)`
/// (`ALSMantleComponent.h:48`), which is where the 1 m clip's LH/RH pair comes
/// from: a character carrying something in its right hand reaches with its left.
pub const MANTLE_VAR: &str = "mantle";
/// [`MANTLE_VAR`]'s value for a low mantle led by the right hand.
pub const MANTLE_LOW_RH: f64 = 1.0;
/// [`MANTLE_VAR`]'s value for a low mantle led by the left hand.
pub const MANTLE_LOW_LH: f64 = 2.0;
/// [`MANTLE_VAR`]'s value for a high mantle.
pub const MANTLE_HIGH: f64 = 3.0;
/// **The clip time a mantle's animation should be entered at**, seconds — ALS's
/// `MantleParams.StartingPosition` (`ALSMantleComponent.cpp:103-108`), which the
/// height remap produces so a 0.6 m ledge and a 1.2 m one can share one clip.
///
/// P29.4 computed it (`inf_anim::HeightRemap::resolve`) and stored it on
/// `MantleState::clip_start_s`, and nothing could consume it because a state
/// machine had no way to enter a state anywhere but at its beginning. The pose
/// step reads it here and hands it to
/// `inf_anim::SmContext::with_entry_offset`.
pub const MANTLE_START_VAR: &str = "mantle_start";

/// Which state [`MANTLE_VAR`]'s value names, or `None` for "no mantle".
///
/// The one place the four values and the three state names are held together,
/// so a reader that needs to go from the parameter back to the row does not
/// re-spell the table.
pub fn mantle_state_name(param: f64) -> Option<&'static str> {
    if param == MANTLE_LOW_RH {
        Some("mantle_low")
    } else if param == MANTLE_LOW_LH {
        Some("mantle_low_lh")
    } else if param == MANTLE_HIGH {
        Some("mantle_high")
    } else {
        None
    }
}
/// **How fast the machine should play its cycle** (wave CHAR1b.2) — ALS's
/// `CalculateStandingPlayRate` (`ALSCharacterAnimInstance.cpp:754-769`).
///
/// The character's own ground speed divided by the speed the blended clip
/// depicts, so a sprint whose clip was authored at 5 m/s and a character
/// travelling at 6.5 m/s plays 1.3x and its feet keep up with the ground. This
/// is **stride warping's** first half: a foot that travels at the capsule's
/// speed does not slide.
pub const PLAY_RATE_VAR: &str = "play_rate";
/// **What class of cover the character is in** (wave COV1): `0` none, `1` low
/// (crouched behind a car or a counter), `2` high (standing against a wall).
///
/// A float and not a state name, which is the CHAR1b.2 law: the door is a MODE
/// plus a PARAMETER. `inf_ecs::cover::CoverClass::param` is the one place the
/// numbers are minted and `from_param` reads them back, so a gate compares
/// against the enum rather than against a literal.
pub const COVER_VAR: &str = "cover";
/// [`COVER_VAR`]'s value for a low (crouched) cover.
pub const COVER_LOW: f64 = 1.0;
/// [`COVER_VAR`]'s value for a high (standing) cover.
pub const COVER_HIGH: f64 = 2.0;
/// **Which way the character is leaning out of cover** (wave COV1): `0` tucked
/// in, `-1` around its left edge, `+1` around its right, `2` over the top.
///
/// Read by the POSE step's additive lean rather than by an edge — a peek is a
/// layer over the cover stance, not a state of its own, for the reason the
/// throws are overlays and not states.
pub const COVER_SIDE_VAR: &str = "cover_side";
/// **How far out that lean is**, `[0, 1]` (wave COV1). The additive's own alpha.
pub const COVER_PEEK_VAR: &str = "cover_peek";
/// **Lean, left/right**, `[-1, 1]` — ALS's `LeanAmount.LR`
/// (`ALSCharacterAnimInstance.cpp:633-637`), positive to the character's right.
pub const LEAN_X_VAR: &str = "lean_x";
/// **Lean, forward/back**, `[-1, 1]` — ALS's `LeanAmount.FB`, positive ahead.
pub const LEAN_Y_VAR: &str = "lean_y";
/// **How far the character will travel before it stops**, metres (wave
/// CHAR1b.2) — the input to distance matching on a stop.
///
/// `v^2 / (2 a)` at the current planar speed and braking deceleration, and `0`
/// while the stick is still pushed. A stop is a DECISION taken while the
/// character is still moving, which is what makes the two stop clips reachable:
/// waiting until the speed has already fallen is waiting until the stop is over.
pub const STOP_DISTANCE_VAR: &str = "stop_distance";
/// The angle at which a turn-in-place is a 180 rather than a 90, degrees.
///
/// Halfway between the two clips the donor ships, so each plays for the turns it
/// is nearer to — ALS picks the same way, off `TurnInPlaceValues`.
pub const TURN_180_DEG: f64 = 135.0;
/// The smallest turn that plays a clip at all, degrees — ALS's
/// `TurnCheckMinAngle`, which `inf_ecs::movement::turn_in_place` already gates
/// the runtime on. Repeated here as the graph's own floor, so a machine driven
/// by a hand-written parameter set behaves like one driven by the movement step.
pub const TURN_MIN_DEG: f64 = 45.0;
/// **The lateral half of the movement direction in the character's own frame**,
/// `[-1, 1]`, positive to its right (wave CHAR1b.1).
///
/// P29 published a four-value `direction` quadrant, which is enough to pick a
/// clip and not enough to *blend* between six of them. A blend space needs a
/// plane, so the movement step publishes one.
pub const MOVE_X_VAR: &str = "move_x";
/// The forward half of the same, positive ahead.
pub const MOVE_Y_VAR: &str = "move_y";

/// The engine movement mode a slot serves.
///
/// The discriminants are `inf_ecs::components::MovementMode`'s, mirrored because
/// the ring order forbids naming it; the gate holds them together.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum LocoMode {
    /// Standing locomotion.
    Grounded = 0,
    /// Crouched.
    Crouch = 1,
    /// Prone (wave CHAR1b.2).
    Prone = 2,
    /// A crouch-sprint slide (wave CHAR1b.2).
    Slide = 3,
    /// A roll.
    Roll = 4,
    /// Airborne with full authority — a deliberate jump.
    FallFree = 6,
    /// Airborne with reduced authority — walked off a ledge, or knocked back.
    FallControlled = 7,
    /// Swimming at the surface (wave CHAR1b.2).
    SwimSurface = 8,
    /// Fully submerged (wave CHAR1b.2).
    SwimUnder = 9,
    /// Mantling or vaulting a ledge (wave CHAR1b.2).
    Mantle = 10,
    /// Physics-driven ragdoll.
    Ragdoll = 11,
    /// **Taking cover** behind a surface (wave COV1). Claimed reserved slot 14,
    /// so the number is 14 and not 12 — `Driving` and `Flying` hold 12 and 13
    /// and are not animated by this graph.
    Cover = 14,
}

impl LocoMode {
    /// The `mode` parameter value a machine compares against.
    pub const fn param(self) -> f64 {
        self as u8 as f64
    }
}

/// What kind of thing a slot is, which decides where it is bound.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SlotKind {
    /// A state of the locomotion graph — the machine plays it.
    State,
    /// A **weapon overlay pose set**, played on the additive layer rather than
    /// by the machine (ALS's own structure: an overlay is a layered blend over
    /// whatever the locomotion graph is doing). Listed here so the map is the
    /// one place a reader looks for "what plays what", and bound by
    /// [`crate::layers`]'s stack rather than by [`build_locomotion_graph`].
    Overlay,
    /// An **aim sweep** — a 2D additive blend space driven by aim yaw and pitch.
    AimSweep,
}

/// One slot of the locomotion graph: a state name, the mode it serves, and the
/// ALS sequences that fill it.
#[derive(Clone, Copy, Debug)]
pub struct LocoSlot {
    /// The machine state's name, or the layer's.
    pub state: &'static str,
    /// The engine mode this slot animates.
    pub mode: LocoMode,
    /// Where it is bound.
    pub kind: SlotKind,
    /// Whether the motion loops (a cycle) or holds its last pose (a one-shot).
    pub looping: bool,
    /// The ALS sequences and their blend coordinates in `(move_x, move_y)`.
    ///
    /// One entry is a single clip; more than one is a [`BlendSpace2D`] over
    /// those coordinates. The coordinates are the donor's own directions:
    /// forward is `+y`, the character's right is `+x`, and a diagonal is the
    /// unit-ish corner ALS authored it at.
    pub clips: &'static [(&'static str, [f64; 2])],
}

/// The forward sample of a direction blend.
const F: [f64; 2] = [0.0, 1.0];
/// Backward.
const B: [f64; 2] = [0.0, -1.0];
/// Left-forward. **On the diamond `|x| + |y| = 1`, not the square**: the
/// movement step publishes ALS's own normalization (`Sum = |X| + |Y|`, so a
/// diagonal is `0.5, 0.5`), and a sample at `(1, 1)` would be a clip the blend
/// could never reach.
const LF: [f64; 2] = [-0.5, 0.5];
/// Right-forward. See [`LF`].
const RF: [f64; 2] = [0.5, 0.5];
/// Left-backward. See [`LF`].
const LB: [f64; 2] = [-0.5, -0.5];
/// Right-backward. See [`LF`].
const RB: [f64; 2] = [0.5, -0.5];
/// Left.
const L: [f64; 2] = [-1.0, 0.0];
/// Right.
const R: [f64; 2] = [1.0, 0.0];
/// The single sample of a clip that is not a direction blend.
const O: [f64; 2] = [0.0, 0.0];

